const { PDFDocument } = require('pdf-lib');
const fontkit = require('@pdf-lib/fontkit');
const fs = require('fs');

(async () => {
  const doc = await PDFDocument.create();
  doc.registerFontkit(fontkit);
  const cjkPath = process.env.SKILL_SANDBOX_CJK_FONT || '/usr/share/fonts/workspacex/NotoSansSC-Common.otf';
  const font = await doc.embedFont(fs.readFileSync(cjkPath));

  const pageW = 595, pageH = 842;
  const ml = 50, mr = 50, mt = 60, mb = 50;
  const contentW = pageW - ml - mr;

  function addPage() { return doc.addPage([pageW, pageH]); }

  // --- Page 1: Title + Overview ---
  let page = addPage();
  let y = pageH - mt;

  page.drawText('AI Agent 能力总览', { x: ml, y, size: 28, font });
  y -= 18;
  page.drawLine({ start: { x: ml, y }, end: { x: pageW - mr, y }, thickness: 1.2 });
  y -= 30;

  const intro = [
    '本文档总结了当前 AI Agent 可以为您完成的核心工作，涵盖文档生成、数据分析、',
    '信息检索、会议支持、可视化、研究规划等多个领域。每项能力均对应一个专用技能',
    '模块，确保输出质量可控、流程可复现。'
  ];
  for (const line of intro) {
    page.drawText(line, { x: ml, y, size: 12, font });
    y -= 20;
  }
  y -= 20;

  // Section helper
  function drawSection(pg, startY, title, items) {
    let cy = startY;
    pg.drawText(title, { x: ml, y: cy, size: 16, font });
    cy -= 8;
    pg.drawLine({ start: { x: ml, y: cy }, end: { x: ml + contentW, y: cy }, thickness: 0.6 });
    cy -= 22;
    for (const item of items) {
      if (cy < mb + 20) { return cy; } // overflow guard
      // bullet
      pg.drawText('•', { x: ml + 4, y: cy, size: 12, font });
      pg.drawText(item, { x: ml + 20, y: cy, size: 11, font });
      cy -= 19;
    }
    return cy;
  }

  // Sections on page 1
  y = drawSection(page, y, '一、文档与办公文件生成', [
    '创建 PDF 文档：报告、说明手册、排版好的单页或多页文档',
    '创建 Word (.docx) 文档：正式公文、合同草稿、内部通知',
    '创建 Excel (.xlsx) 表格：数据报表、预算模板、清单',
    '创建 PowerPoint (.pptx) 演示文稿：汇报幻灯片、培训材料',
  ]);
  y -= 14;
  y = drawSection(page, y, '二、数据分析与可视化', [
    '分析 CSV / XLSX / JSON 数据，给出可复现的计算结果与结论',
    '生成静态图表（柱状图、折线图、饼图等），校验中文标签与单位',
    '数据质量检查：缺失值、异常值、格式一致性审计',
  ]);
  y -= 14;
  y = drawSection(page, y, '三、信息检索与研究', [
    '联网搜索公开资料，形成带引用的研究报告',
    '基于组织内部知识库回答问题，附带出处定位',
    '用户研究规划：将研究目标转化为招募条件与访谈提纲',
  ]);

  // --- Page 2 ---
  page = addPage();
  y = pageH - mt;

  y = drawSection(page, y, '四、会议与沟通支持', [
    '会议准备：背景材料、议程、预读文档与决策问题整理',
    '会议纪要：从转录文本提炼关键决议与行动项，标注证据位置',
    '访谈综合：多场访谈去重、主题归纳、引文定位与反例标注',
    '内部沟通稿：公告、领导更新、FAQ、项目周报草稿',
    '项目状态报告：里程碑进展、风险摘要、领导简报',
  ]);
  y -= 14;
  y = drawSection(page, y, '五、多媒体与创意', [
    '音频转文字：保留时间范围与识别局限说明',
    '视觉内容创作：海报构图、配图文案、精确排版交付',
    '交互式网页产物：自包含 HTML，支持响应式布局与状态交互',
    '画布与流程图：Mermaid / Fabric 画布编辑与导出',
  ]);
  y -= 14;
  y = drawSection(page, y, '六、文档理解与处理', [
    '读取上传的 PDF / Office / CSV 原件，提取可核验内容',
    'PDF 表单填写（标准 AcroForm 文本域与复选框）',
    '扫描件 OCR 识别与表格提取',
  ]);
  y -= 14;
  y = drawSection(page, y, '七、技能扩展与管理', [
    '将重复性工作流封装为可复用技能草稿包',
    'MAAU 画布：把会议/需求讨论提炼为最小智能体可执行单元',
  ]);

  // Footer note
  y -= 30;
  page.drawLine({ start: { x: ml, y }, end: { x: pageW - mr, y }, thickness: 0.4 });
  y -= 18;
  page.drawText('以上能力均由专用技能模块驱动，输出可追溯、流程可复现。', { x: ml, y, size: 10, font });
  y -= 16;
  page.drawText('如需了解某项能力的详细说明或使用示例，请直接询问。', { x: ml, y, size: 10, font });

  const outPath = '/workspace/agent-capabilities.pdf';
  fs.writeFileSync(outPath, await doc.save());
  console.log('OK:', outPath);
})().catch(e => { console.error(e.stack); process.exit(1); });
